class Bubble{transitionTimestamp=null
constructor(){let speedLimitMin=map(minWindowDim,320,4000,2,10,!0)
let speedLimitMax=map(minWindowDim,320,4000,9,50,!0)
let theta=fxrandRange(0,360)
let x=width/2+(cos(theta)*minWindowDim*0.45)
let y=height/2+(sin(theta)*minWindowDim*0.45)
if(fxrandBool()){x=width/2
y=height/2}
this.position=createVector(x,y)
this.velocity=createVector(0,0)
this.acceleration=createVector(0,0)
this.speedLimit=fxrandRange(speedLimitMin,speedLimitMax)
this.mass=fxrandRange(10,100)
this.repelDistance=minWindowDim*fxrandRange(0.05,0.3)
this.targetPosition=createVector(this.position.x,this.position.y)}
update(alphaAddOn){if((!touch||mouseIsPressed)&&mouseX>0&&mouseX<width&&mouseY>0&&mouseY<height){let mousePos=createVector(mouseX,mouseY)
let direction=p5.Vector.sub(mousePos,this.position)
let distance=direction.mag()
if(distance<this.repelDistance){direction.normalize()
let repellentForce=-(distance*gravity)
let force=p5.Vector.mult(direction,repellentForce)
this.acceleration.add(force)}}
let direction=p5.Vector.sub(this.targetPosition,this.position)
this.distanceFromHome=direction.mag()
direction.normalize()
let strength=(this.distanceFromHome*0.1)/this.mass
let bounce=0.95
strength=(this.distanceFromHome*0.1)/(this.mass*(1-(bounce-0.01)))
let force=p5.Vector.mult(direction,strength)
this.acceleration.add(force)
this.velocity.mult(0.96)
this.velocity.add(this.acceleration)
this.velocity.limit(this.speedLimit)
this.position.add(this.velocity)
this.acceleration.mult(0)
let hue=this.hue
let saturation=this.saturation
let brightness=this.brightness
let alpha=this.alpha
let size=this.size
let duration=1000
let timeElapsed=Date.now()-this.transitionTimestamp
if(this.transitionTimestamp!=null&&timeElapsed<duration){hue=map(timeElapsed,0,duration,this.oldHue,this.hue)
saturation=map(timeElapsed,0,duration,this.oldSaturation,this.saturation)
brightness=map(timeElapsed,0,duration,this.oldBrightness,this.brightness)
alpha=map(timeElapsed,0,duration,this.oldAlpha,this.alpha)
size=map(timeElapsed,0,duration,this.oldSize,this.size)}
alpha+=alphaAddOn
alpha=min(this.alpha,max(0,alpha))
let bAdd=(brightness>0)?map(this.position.x,width*0.25,width*0.75,-20,20):0
let x=this.position.x
let y=this.position.y
fill(hue,saturation,brightness+bAdd,alpha)
if(isGlitching){y+=(x>width/2)?minWindowDim/70:-minWindowDim/70}
ellipse(x,y,size)}
setOldValuesFrom(bubble){this.transitionTimestamp=Date.now()
this.oldHue=bubble.hue
this.oldSaturation=bubble.saturation
this.oldBrightness=bubble.brightness
this.oldAlpha=bubble.alpha
this.oldSize=bubble.size
this.position.x=bubble.position.x
this.position.y=bubble.position.y}
moveToTarget(){this.position.x=this.targetPosition.x
this.position.y=this.targetPosition.y}
scale(scale){this.size*=scale}}
class BubbleRing{ringNum=0
ringType=null
colourType=null
maxBubbleSize=0
bubbles=[]
alphaIncrement=0
alphaAddOn=0
constructor(numBubbles,maxBubbleSize){this.maxBubbleSize=maxBubbleSize
this.bubbles=[]
for(let pos=0;pos<numBubbles;pos++){let bubble=new Bubble(!0)
this.bubbles.push(bubble)}}
glitch(){for(const bubble of this.bubbles){let minMove=minWindowDim/80
if(fxrandBool()){let gap=minWindowDim/10
let xBand=floor(bubble.position.x/gap)
if(xBand%2==0){bubble.position.y+=fxrandRange(minMove,minMove*2)}else{bubble.position.y-=fxrandRange(minMove,minMove*2)}}else{let gap=height/10
let yBand=floor(bubble.position.y/gap)
if(yBand%2==0){bubble.position.x+=fxrandRange(minMove,minMove*2)}else{bubble.position.x-=fxrandRange(minMove,minMove*2)}}}}
unglitch(){for(const bubble of this.bubbles){bubble.position.x=bubble.targetPosition.x
bubble.position.y=bubble.targetPosition.y}}
setOldValuesFrom(ring){for(let i=0;i<this.bubbles.length;i++){this.bubbles[i].setOldValuesFrom(ring.bubbles[i])}}
scale(scale){this.maxBubbleSize*=scale
for(const bubble of this.bubbles){bubble.scale(scale)}}
moveToTarget(){for(const bubble of this.bubbles){bubble.moveToTarget()}}
initialiseBubbles(ringNum,ringType,colourType){this.ringType=ringType
this.colourType=colourType
this.ringNum=ringNum
let maxRadius=minWindowDim/4
let radius=(maxRadius/this.numRings)*this.ringNum
let numCentres=2+(this.ringNum*2)
let numInStack=400/numCentres
let firstB=this.bubbles[0]
let numBubbles=this.bubbles.length
for(let pos=0;pos<numBubbles;pos++){let bubble=this.bubbles[pos]
let p=pos-(pos%numInStack)
let stackNum=floor(p/numInStack)
bubble.alpha=fxrandRange(30,50)
bubble.hue=fxrandRange(0,360)
bubble.brightness=fxrandRange(20,70)
bubble.saturation=fxrandRange(20,70)
bubble.size=fxrandRange(20,100)
switch(this.colourType){case MONOTONE:bubble.brightness=fxrandRange(40,60)
this.saturation=fxrandRange(40,60)
if(pos>0){bubble.hue=firstB.hue
bubble.saturation=fxrandRange(30,70)
bubble.brightness=fxrandRange(30,70)}
break
case RAINBOW:bubble.hue=360*pos/numBubbles
bubble.saturation=fxrandRange(40,60)
bubble.brightness=fxrandRange(40,60)
break
case GREYSCALE:bubble.saturation=fxrandRange(0,20)
bubble.brightness=fxrandRange(30,70)
break
case ALTERNATING:let complementaryHue=(firstB.hue+180)%360
if(this.ringType==TWIN){bubble.hue=(pos%2==0)?firstB.hue:complementaryHue}else if(this.ringType==DOUGHNUTS){p=pos-(pos%(numInStack*0.5))
stackNum=floor(p/(numInStack*0.5))
bubble.hue=((stackNum)%2==0)?firstB.hue:complementaryHue}else{bubble.hue=(stackNum%2==0)?firstB.hue:complementaryHue}
bubble.saturation=fxrandRange(30,70)
bubble.brightness=fxrandRange(30,70)
break
case SHADE:if(pos>0){bubble.hue=firstB.hue
bubble.saturation=(firstB.saturation*fxrand(0.9,1.1))%100}
let prop=(pos%numInStack)/numInStack
if(this.ringNum%2==0){prop=1-prop}
bubble.brightness=map(cos(prop*360),-1,1,10,95)}
switch(this.ringType){case STACKED:bubble.alpha=fxrandRange(40,60)
bubble.mass=50
let sizeReduction=(this.maxBubbleSize*0.8)/numInStack
bubble.size=(this.maxBubbleSize*0.85)-((pos%numInStack)*sizeReduction)
break
case BULGING:let multiplier=sin(270+((pos/numInStack)*360))
bubble.alpha=40
bubble.size=map(multiplier,0,1,this.maxBubbleSize*0.5,this.maxBubbleSize*0.75)
break
case WAVE:bubble.size=this.maxBubbleSize*0.3
bubble.mass=50*fxrandRange(0.9,1.1)
break
case WALTZER:bubble.size=this.maxBubbleSize*0.2
bubble.mass=50*fxrandRange(0.9,1.1)
break
case DIAL:bubble.size=this.maxBubbleSize*0.25
bubble.mass=50*fxrandRange(0.9,1.1)
break
case TWIN:bubble.size=this.maxBubbleSize*0.45*fxrandRange(0.5,1)
bubble.mass=50*fxrandRange(0.9,1.1)
bubble.hue=(bubble.hue*fxrandRange(0.8,1.2))%360
bubble.brightness=(bubble.brightness*fxrandRange(0.8,1.2))%100
break
case DOUGHNUTS:bubble.size=this.maxBubbleSize*0.75*fxrandRange(0.5,1)
bubble.mass=50*fxrandRange(0.9,1.1)
bubble.hue=(bubble.hue*fxrandRange(0.8,1.2))%360
bubble.brightness=(bubble.brightness*fxrandRange(0.8,1.2))%100
if(pos%(numInStack*0.5)>=(numInStack*0.5)-1||pos==numBubbles-1){bubble.brightness=0
bubble.saturation=0
bubble.alpha=100
bubble.size=this.maxBubbleSize*0.3}
break
case COMET:let posInStack=pos%numInStack
let prop=(posInStack/(numInStack))
if(this.ringNum%2==1){prop=1-prop}
bubble.size=(this.maxBubbleSize*0.1)+(prop*this.maxBubbleSize*0.3)}}
this.update()}
update(distMult){let mBS=this.maxBubbleSize
let distanceFromCentre=mBS*this.ringNum
let i=0
let addOn=(tick/6)*(this.ringNum%2==0?1:-1)
let numCentres=2+(this.ringNum*2)
let numInStack=400/numCentres
let xAdd=0
let yAdd=0
this.alphaAddOn+=this.alphaIncrement
for(const bubble of this.bubbles){let bubble=this.bubbles[i]
let pos=i
let dist=distanceFromCentre
let stackPos=i-(i%numInStack)
let stackNum=floor(i/numInStack)
switch(this.ringType){case STACKED:pos=stackPos
break
case WAVE:dist=distanceFromCentre+(sin((((pos+addOn)/numInStack)*360)+270)*mBS*0.22)
break
case WALTZER:pos=stackPos
let theta2=((i%numInStack)/numInStack)*360
theta2=theta2+(-addOn*5)
xAdd=sin(theta2)*mBS*0.325
yAdd=cos(theta2)*mBS*0.325
break
case DIAL:pos=stackPos
let theta3=((i%numInStack)/numInStack)*360
let dots=this.ringNum+5
theta3=(floor(theta3/dots)*(360/dots))-(addOn*5)
let r=mBS*0.175*0.4*(sin(abs(addOn)*6)+3)
xAdd=sin(theta3)*r
yAdd=cos(theta3)*r
break
case DOUGHNUTS:pos=i-(i%(numInStack*0.5))
if(i%(numInStack*0.5)>=(numInStack*0.5)-1||i==this.bubbles.length-1){let m=sin(addOn*10)+3
bubble.size=m*mBS*0.1}
break
case TWIN:pos=i-(i%(numInStack*0.5))
let m=sin(addOn*5)*0.2
dist+=(i%2==0)?mBS*m:-mBS*m
break
case COMET:pos=stackPos+((pos%numInStack)*0.7)}
let theta=((pos/400)*360)+addOn
if(distMult!=null){dist*=distMult}
bubble.targetPosition.x=width/2+(sin(theta)*dist)+xAdd
bubble.targetPosition.y=height/2+(cos(theta)*dist)+yAdd
i+=1}
for(const bubble of this.bubbles){bubble.update(this.alphaAddOn)}}}
class BubbleDesign{numRings=0
rings=[]
constructor(empty){if(!empty){let r=fxrandRange(1,15)
if(r<=8){this.numRings=4}else if(r<=12){this.numRings=5}else if(r<=14){this.numRings=6}else if(r<=15){this.numRings=7}
let maxDistanceFromCentre=minWindowDim/4
let maxBubbleSize=maxDistanceFromCentre/this.numRings
let isHomogeneous=(fxrandRange(1,17)>16)
for(let ringNum=1;ringNum<=this.numRings;ringNum++){let ringType=fxrandChoice(ringTypes)
let colourType=fxrandChoice(colourTypes)
if(isHomogeneous&&ringNum>1){ringType=this.rings[0].ringType
colourType=this.rings[0].colourType}
let ring=new BubbleRing(400,maxBubbleSize)
ring.initialiseBubbles(ringNum,ringType,colourType)
this.rings.push(ring)}}}
setOldValuesFrom(design){let mn=min(this.numRings,design.numRings)
for(let pos=0;pos<mn;pos++){this.rings[pos].setOldValuesFrom(design.rings[pos])}}
moveToTarget(){for(const ring of this.rings){ring.moveToTarget()}}
clear(){this.numRings=0
this.rings=[]}
update(){for(const ring of this.rings){ring.update()}}
scale(scale){for(const ring of this.rings){ring.scale(scale)}}}
const STACKED="stacked"
const BULGING="bulging"
const WAVE="wave"
const WALTZER="waltzer"
const DIAL="dial"
const TWIN="twin"
const DOUGHNUTS="dots"
const COMET="comet"
const MONOTONE="monotone"
const RAINBOW="rainbow"
const GREYSCALE="greyscale"
const ALTERNATING="alternating"
const SHADE="shade"
const ringTypes=[STACKED,BULGING,WAVE,WALTZER,DIAL,TWIN,DOUGHNUTS,COMET]
const colourTypes=[MONOTONE,RAINBOW,GREYSCALE,ALTERNATING,SHADE]
var minWindowDim
var resizeTime=0
var resizeDelay=300
var resizeHandled=!0
var gravity=0
var touch=!1
var tick=0
var canSpark=!1
var canGlitter=!1
var canFlame=!1
var canSnow=!1
var isGlittering=!1
var isFlaming=!1
var isSnowing=!1
var isElectric=!1
var isGlitching=!1
var glitchAgain=!1
var fireStartTick=0
var sparkleStartTick=0
var glitchStartTick=0
var snowStartTick=0
var plasmaStartTick=0
var designPosition=0
var designs=[]
var designPos=-1
var design=new BubbleDesign(!0)
function setup(){tick=0
minWindowDim=min(window.innerWidth,window.innerHeight)
pixelDensity(1)
createCanvas(window.innerWidth-30,window.innerHeight-35)
colorMode(HSB,360,100,100,100)
angleMode(DEGREES)
for(let designNum=0;designNum<3;designNum++){designs.push(new BubbleDesign(!1))}
goToNextDesign()
noStroke()
touch=('ontouchstart' in window)||(navigator.maxTouchPoints>0)||(navigator.msMaxTouchPoints>0)
cursor(HAND);gravity=map(minWindowDim,320,1200,50,900,!0)}
function draw(){tick+=1
background(color(0,0,0))
if(isFlaming){doFire()}
if(isSnowing){doSnowing()}
if(isPlasming){doPlasma(bottomPlasmaStrands)}
design.update()
if(isPlasming){doPlasma(topPlasmaStrands)}
if(isGlittering){doGlitter()}
if(!resizeHandled&&resizeTime+resizeDelay<millis()){let oldMinWindowDim=minWindowDim
minWindowDim=min(window.innerWidth,window.innerHeight)
resizeCanvas(window.innerWidth-30,window.innerHeight-35)
let scale=minWindowDim/oldMinWindowDim
resizePiece(scale)
resizeHandled=!0}
addCircle()}
function resizePiece(scale){for(const design of designs){design.scale(scale)}
if(isSnowing){restartSnow()}
if(isPlasming){restartPlasma()}}
function addCircle(){let prop=(tick%350)/350
let b=30+(70*(1+cos(prop*360)))
stroke(0,10,b,100)
noFill()
strokeWeight(4)
stroke(0,10,b,20)
let mult=0.6
ellipse(width/2,height/2,minWindowDim*0.6)
strokeWeight(2)
ellipse(width/2,height/2,minWindowDim*0.6)
noStroke()}
function goToNextDesign(){let isFirstShowing=(designPos==-1)
let currentDesign=isFirstShowing?null:designs[designPos]
let nextDesign=designs[(designPos+1)%3]
nextDesign.update()
if(!isFirstShowing){nextDesign.moveToTarget()}
design.clear()
design.numRings=nextDesign.numRings
for(let pos=0;pos<nextDesign.numRings;pos++){let ring=nextDesign.rings[pos]
if(currentDesign!=null&&pos>=currentDesign.numRings){ring.alphaAddOn=-50
ring.alphaIncrement=2
ring.update(1.25)
ring.moveToTarget()}else{ring.alphaIncrement=0
ring.alphaAddOn=0}
design.rings.push(ring)}
if(!isFirstShowing){design.setOldValuesFrom(currentDesign)
for(let pos=nextDesign.numRings;pos<currentDesign.numRings;pos++){let ring=currentDesign.rings[pos]
ring.alphaAddOn=0
ring.alphaIncrement=-2
ring.update(4)
design.rings.push(ring)}}
designPos=(designPos+1)%3}
let bottomPlasmaStrands=[]
let topPlasmaStrands=[]
class PlasmaStrand{numParts=0
thetas=[]
radii=[]
nextMoveTick=tick+200
isOnTop=!1
baseHue=0
isDead=!1
constructor(hue,isOnTop){this.baseHue=hue
this.isOnTop=isOnTop
this.numParts=floor(fxrandRange(7,17))
let baseTheta=fxrandRange(0,360)
this.thetas.push(baseTheta)
this.radii.push(minWindowDim*0.3)
let takeOffRadius=(minWindowDim*0.3*0.95)/(this.numParts-1)
for(let i=1;i<=this.numParts;i++){this.thetas.push(baseTheta+fxrandRange(-7,7))
let r=(minWindowDim*0.3)-(i*takeOffRadius)
this.radii.push(r)}}
draw(){if(this.isDead){return}
noFill()
let weights=[8,2]
let alphas=[5,17]
if(this.isOnTop==!0){alphas=[10,25]}
for(let pos=0;pos<weights.length;pos++){let hue=fxrandRange(this.baseHue-30,this.baseHue+30)
stroke(hue,100,50,alphas[pos])
let points=[]
strokeWeight(weights[pos])
for(let i=0;i<this.numParts;i++){let x=width/2+(sin(this.thetas[i])*this.radii[i])
let y=height/2+(cos(this.thetas[i])*this.radii[i])
points.push(createVector(x,y))
beginShape()
for(let i=0;i<points.length;i++){const pt=points[i]
if(i==0)curveVertex(pt.x,pt.y)
curveVertex(pt.x,pt.y)
if(i==points.length-1)curveVertex(pt.x,pt.y)}
endShape()}}
noStroke()}
update(){if(fxrandRange(0,10)<1&&this.nextMoveTick<tick){this.thetas[0]=fxrandRange(0,360)
this.nextMoveTick=tick+100
if(this.isOnTop==!0){this.isDead=!0}}
let takeOffRadius=minWindowDim*0.3/this.numParts
let baseTheta=this.thetas[0]
for(let i=1;i<this.numParts-1;i++){this.thetas[i]=baseTheta+fxrandRange(-7,7)
let r=(minWindowDim*0.3)-(i*takeOffRadius)
this.radii[i]=r}}}
function restartPlasma(){bottomPlasmaStrands=[]
topPlasmaStrands=[]
plasmaStartTick=tick
for(let i=0;i<7;i++){bottomPlasmaStrands.push(new PlasmaStrand(300,!1))}
for(let i=0;i<20;i++){topPlasmaStrands.push(new PlasmaStrand(200,!0))}}
function doPlasma(plasmaStrands){if(plasmaStrands.length==0){restartPlasma()}
for(const strand of plasmaStrands){strand.draw()
if(fxrandRange(0,10)<1){strand.update()}}}
function doGlitter(){for(let ringNum=1;ringNum<=design.numRings;ringNum++){for(const bubble of design.rings[ringNum-1].bubbles){if(fxrand()>0.9){let xAdd=fxrandRange(-bubble.size*0.4,bubble.size*0.4)
let yAdd=fxrandRange(-bubble.size*0.4,bubble.size*0.4)
addGlitter(bubble.position.x+xAdd,bubble.position.y+yAdd,60)}}
for(let i=0;i<10;i++){let theta=fxrandRange(0,360)
let x=width/2+(sin(theta)*minWindowDim*0.3)
let y=height/2+(cos(theta)*minWindowDim*0.3)
addGlitter(x,y,60)}
for(let i=0;i<30;i++){let theta=fxrandRange(0,360)
let x=width/2+(sin(theta)*minWindowDim*fxrandRange(0,0.3))
let y=height/2+(cos(theta)*minWindowDim*fxrandRange(0,0.3))
addGlitter(x,y,0)}}}
function addGlitter(x,y,lowAlpha){let prop=min(1,(tick-sparkleStartTick)/100)
let alpha=map(prop,0,1,100,lowAlpha)
let h=fxrandRange(50,60)
fill(h,100,100,alpha)
let r=fxrandRange(1,5)
ellipse(x,y,r)}
function doFire(){for(let i=0;i<350;i++){let maxTheta=min(1,(tick-fireStartTick)/300)*360
let theta=180-fxrandRange(0,maxTheta)
let maxDist=minWindowDim*0.08
let dist=fxrandRange(0,maxDist)
let hue=map(dist,0,maxDist,30,60)
let alpha=map(dist,0,maxDist,30,10)
let rad=(minWindowDim*0.3)+dist
let rX=width/2+(sin(theta)*rad)
let rY=height/2+(cos(theta)*rad)
fill(hue,100,100,alpha)
let size=map(dist,0,maxDist,minWindowDim*0.2,minWindowDim*0.05)
ellipse(rX,rY,size/10)}}
var snowFlakes=[]
class SnowFlake{x=0
y=0
xSpeed=0
ySpeed=0
size=0
alpha=0
mustBeInCircle=!1
constructor(){this.x=fxrandRange(width/2-minWindowDim/3,width/2+minWindowDim/3)
this.y=fxrandRange(0,-height)
this.xSpeed=fxrandRange(0.1,0.5)
this.ySpeed=fxrandRange(1,2)
this.size=fxrandRange(minWindowDim*0.001,minWindowDim*0.01)
this.alpha=fxrandRange(20,40)}
move(){this.y+=this.ySpeed
this.x+=this.xSpeed*fxrandRange(-1,1)
if(this.y>height){this.y=0
this.mustBeInCircle=!0}}
draw(){let xDist=this.x-width/2
let yDist=this.y-height/2
let distFromCentre=sqrt((xDist*xDist)+(yDist*yDist))
if(!this.mustBeInCircle||distFromCentre<minWindowDim*0.3){fill(200,100,100,this.alpha)
ellipse(this.x,this.y,this.size)}}}
function doSnowing(){if(snowFlakes.length==0){restartSnow()}
for(const flake of snowFlakes){flake.move()
flake.draw()}}
function restartSnow(){snowFlakes=[]
for(let i=0;i<250;i++){snowFlakes.push(new SnowFlake())}}
function doGlitch(){if(glitchAgain||fxrandRange(0,20)<1){if(fxrandRange(0,20)<1){fill(0,0,0,fxrandRange(50,90))
square(0,0,width,height)}
if(glitchAgain){for(const ring of design.rings){ring.unglitch()}}
glitchAgain=!glitchAgain
if(fxrandRange(0,20)<1){for(const ring of design.rings){ring.glitch()}}
if(fxrandRange(0,20)<1){tick=max(1,tick+fxrandRange(-50,50))}}}
function doResize(){resizeTime=millis()
resizeHandled=!1}
function fxrandRange(low,high){return low+(fxrand()*(high-low))}
function fxrandBool(){return fxrand()<0.5}
function fxrandChoice(list){let pos=floor(fxrandRange(0,list.length-0.001))
return list[pos]}
function mousePressed(){goToNextDesign()}
function keyTyped(){if(key=="f"&&canFlame){isFlaming=!isFlaming;fireStartTick=tick}
if(key=="g"&&canGlitter){isGlittering=!isGlittering;sparkleStartTick=tick}
if(key=="p"&&canSpark){isPlasming=!isPlasming;restartPlasma()}
if(key=="s"&&canSnow){isSnowing=!isSnowing;restartSnow()}
return!1}
console.print=function(...args){queueMicrotask(console.log.bind(console,...args))}
canGlitter=(fxrandRange(1,17)>16);isGlittering=canGlitter
canFlame=(fxrandRange(1,17)>16);isFlaming=canFlame
canSnow=(fxrandRange(1,17)>16);isSnowing=canSnow
canSpark=(fxrandRange(1,17)>16);isPlasming=canSpark
window.$fxhashFeatures={"Fire":canFlame,"Glitter":canGlitter,"Plasma":canSpark,"Snow":canSnow}
window.addEventListener('resize',doResize)
